-- name: GetDeliveryCompletionAuthorization :one
SELECT * FROM delivery_completion_authorization WHERE id=$1;

-- name: LockDeliveryCompletionAuthorization :one
SELECT * FROM delivery_completion_authorization WHERE id=$1 FOR UPDATE NOWAIT;

-- name: GetDeliveryCompletionByRequest :one
SELECT * FROM delivery_completion_authorization WHERE workspace_id=$1 AND issuer_user_id=$2 AND request_key=$3 FOR UPDATE NOWAIT;

-- name: GetDeliveryCompletionTerminal :one
SELECT * FROM delivery_completion_terminal WHERE authorization_id=$1;

-- name: CreateDeliveryCompletionAuthorization :one
INSERT INTO delivery_completion_authorization (id, workspace_id, issuer_user_id, request_key, operation_id, contract_version, request_digest, request_json, created_at, expires_at, reason, target_kind, issue_id, issue_revision, expected_status, target_status, target_position, project_id, project_revision, policy_revision, evidence_issue_id, evidence_issue_revision, approval_id, execution_id, producer_agent_id, producer_task_id, producer_generation, spec_digest, artifact_digest, receipt_digest, source_revision, evidence_expires_at, observation, consumer_kind, consumer_user_id, consumer_agent_id, consumer_task_id, consumer_task_generation, consumer_runtime_id, consumer_originator_user_id, consumer_binding_id, consumer_binding_epoch, integration_id, integration_trust_revision, github_installation_id, vcs_provider, vcs_instance_url, webhook_config_identity, pull_request_id, repo_owner, repo_name, pr_number, pr_head_sha, collaboration_revision, lifecycle_epoch, participant_epoch, account_epoch, status_options_version, submission_id, submission_event_seq, delivery_intent_digest, admin_organization_id, issuer_credential_kind, issuer_credential_expires_at, issuer_pat_id, issuer_pat_hash, issuer_password_mode, issuer_password_version, issuer_password_kind, issuer_binding_id, issuer_binding_epoch, issuer_binding_workspace_id, issuer_binding_daemon_id)
VALUES (sqlc.arg('id'), sqlc.arg('workspace_id'), sqlc.arg('issuer_user_id'), sqlc.arg('request_key'), sqlc.arg('operation_id'), sqlc.arg('contract_version'), sqlc.arg('request_digest'), sqlc.arg('request_json'), sqlc.arg('created_at'), sqlc.arg('expires_at'), sqlc.arg('reason'), sqlc.arg('target_kind'), sqlc.arg('issue_id'), sqlc.arg('issue_revision'), sqlc.arg('expected_status'), sqlc.arg('target_status'), sqlc.narg('target_position'), sqlc.arg('project_id'), sqlc.arg('project_revision'), sqlc.arg('policy_revision'), sqlc.arg('evidence_issue_id'), sqlc.arg('evidence_issue_revision'), sqlc.arg('approval_id'), sqlc.arg('execution_id'), sqlc.arg('producer_agent_id'), sqlc.arg('producer_task_id'), sqlc.arg('producer_generation'), sqlc.arg('spec_digest'), sqlc.arg('artifact_digest'), sqlc.arg('receipt_digest'), sqlc.arg('source_revision'), sqlc.arg('evidence_expires_at'), sqlc.arg('observation'), sqlc.arg('consumer_kind'), sqlc.narg('consumer_user_id'), sqlc.narg('consumer_agent_id'), sqlc.narg('consumer_task_id'), sqlc.narg('consumer_task_generation'), sqlc.narg('consumer_runtime_id'), sqlc.narg('consumer_originator_user_id'), sqlc.narg('consumer_binding_id'), sqlc.narg('consumer_binding_epoch'), sqlc.narg('integration_id'), sqlc.narg('integration_trust_revision'), sqlc.narg('github_installation_id'), sqlc.narg('vcs_provider'), sqlc.narg('vcs_instance_url'), sqlc.narg('webhook_config_identity'), sqlc.narg('pull_request_id'), sqlc.narg('repo_owner'), sqlc.narg('repo_name'), sqlc.narg('pr_number'), sqlc.narg('pr_head_sha'), sqlc.narg('collaboration_revision'), sqlc.narg('lifecycle_epoch'), sqlc.narg('participant_epoch'), sqlc.narg('account_epoch'), sqlc.narg('status_options_version'), sqlc.narg('submission_id'), sqlc.narg('submission_event_seq'), sqlc.narg('delivery_intent_digest'), sqlc.narg('admin_organization_id'), sqlc.arg('issuer_credential_kind'), sqlc.narg('issuer_credential_expires_at'), sqlc.narg('issuer_pat_id'), sqlc.narg('issuer_pat_hash'), sqlc.arg('issuer_password_mode'), sqlc.narg('issuer_password_version'), sqlc.narg('issuer_password_kind'), sqlc.narg('issuer_binding_id'), sqlc.narg('issuer_binding_epoch'), sqlc.narg('issuer_binding_workspace_id'), sqlc.narg('issuer_binding_daemon_id'))
ON CONFLICT DO NOTHING RETURNING *;

-- name: CreateDeliveryCompletionTerminal :one
INSERT INTO delivery_completion_terminal (authorization_id, kind, actor_kind, actor_user_id, actor_agent_id, integration_id, operation_id, mutation_digest, issue_revision_before, issue_revision_after, status_after, collaboration_operation_id, admin_operation_id, result_submission_id, result_collaboration_revision, provider_event_id, provider_event_digest, revoker_user_id, revocation_request_key, revocation_reason, revocation_digest)
SELECT sqlc.arg('authorization_id'), sqlc.arg('kind'), sqlc.arg('actor_kind'), sqlc.narg('actor_user_id'), sqlc.narg('actor_agent_id'), sqlc.narg('integration_id'), sqlc.narg('operation_id'), sqlc.narg('mutation_digest'), sqlc.narg('issue_revision_before'), sqlc.narg('issue_revision_after'), sqlc.narg('status_after'), sqlc.narg('collaboration_operation_id'), sqlc.narg('admin_operation_id'), sqlc.narg('result_submission_id'), sqlc.narg('result_collaboration_revision'), sqlc.narg('provider_event_id'), sqlc.narg('provider_event_digest'), sqlc.narg('revoker_user_id'), sqlc.narg('revocation_request_key'), sqlc.narg('revocation_reason'), sqlc.narg('revocation_digest')
WHERE sqlc.arg('kind')::text='revoked'
   OR (sqlc.arg('kind')::text='consumed' AND EXISTS (
       SELECT 1 FROM delivery_completion_authorization a
       WHERE a.id=sqlc.arg('authorization_id') AND a.operation_id=sqlc.narg('operation_id')
         AND a.expires_at>clock_timestamp()
         AND a.evidence_expires_at>clock_timestamp()
         AND (a.issuer_credential_expires_at IS NULL OR a.issuer_credential_expires_at>clock_timestamp())
         AND (sqlc.narg('consumer_expires_at')::timestamptz IS NULL OR sqlc.narg('consumer_expires_at')::timestamptz>clock_timestamp())
   ))
ON CONFLICT DO NOTHING RETURNING *;
